#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex re(R"(^#\s*([0-9]+)\s*([a-zA-Z0-9_]+)");
    std::smatch match;
    while (std::regex_search(html, match, re)) {
        html = html.replace(match.position(), match.length(), "<h" + std::to_string(match[1].length()) + ">" + match[2] + "</h>");
    }
    return html;
}
```

